os.makedirs(OUT, exist_ok=True)
for idx, lang in enumerate(['pt', 'en', 'es']):
    d = {'@@locale': lang}
    for k, (pt, en, es, meta) in S.items():
        d[k] = (pt, en, es)[idx]
        if lang == 'pt' and meta:
            d['@' + k] = meta
    with open(os.path.join(OUT, f'app_{lang}.arb'), 'w', encoding='utf-8', newline='\n') as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
        f.write('\n')
print(len(S), 'keys')
